session_start();header('Content-Type: application/json; charset=utf-8');require_once __DIR__.'/config.php';$action=$_GET['action']??'stats';if($action==='hit'){ $p=json_decode(file_get_contents('php://input'),true);if(!is_array($p))$p=[];$path=substr((string)($p['path']??''),0,500);$tg=substr((string)($p['telegram_id']??''),0,100);$ad=substr((string)($p['ad_id']??''),0,64);$st=$pdo->prepare('INSERT INTO visits (telegram_id,path,ad_id,ip_address,user_agent) VALUES (?,?,?,?,?)');$st->execute([$tg?:null,$path,$ad?:null,$_SERVER['REMOTE_ADDR']??null,substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,1000)]);echo json_encode(['success'=>true]);exit;}if($action==='list'){if(empty($_SESSION['is_admin'])){http_response_code(403);echo json_encode(['success'=>false,'message'=>'دسترسی غیرمجاز']);exit;}$st=$pdo->query("SELECT telegram_id,path,ad_id,ip_address,visited_at FROM visits ORDER BY visited_at DESC LIMIT 100");echo json_encode(['success'=>true,'visits'=>$st->fetchAll(PDO::FETCH_ASSOC)],JSON_UNESCAPED_UNICODE);exit;}
